export {BUILDINGS,UNITS,RESOURCE_KEYS,SIZE,buildingStats,unitStats,DIFFICULTIES,isBuildable,isRecruitable};
const ok=message=>({ok:true,message}),fail=message=>({ok:false,message}),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const rand=W.randomTile;
export {mapSize,sectorId,sectorOrigin,owns,expansionQuote,productionOptions} from './world.js';
export const hqLevel=s=>s.buildings.find(b=>b.type==='hq')?.level||1;
export const builders=s=>2+s.buildings.filter(b=>b.type==='builders'&&b.hp>0&&!b.job).length;
export const usedBuilders=s=>s.buildings.filter(b=>b.job).length+(s.world?.bridges.filter(b=>b.job).length||0);
export const population=s=>colonyPopulation(s)+s.army.reduce((n,u)=>n+UNITS[u.type].pop,0)+s.training.reduce((n,j)=>n+UNITS[j.type].pop,0)+(s.battle?[...s.battle.reserve,...s.battle.units.filter(u=>u.side==='player'&&u.hp>0)].reduce((n,u)=>n+UNITS[u.type].pop,0):0);
export const populationCap=s=>18+s.buildings.filter(b=>BUILDINGS[b.type].population&&b.hp>0).reduce((n,b)=>n+BUILDINGS[b.type].population+2*(b.level-1),0);
export const storageCap=s=>2200+s.buildings.filter(b=>BUILDINGS[b.type].storage&&b.hp>0).reduce((n,b)=>n+BUILDINGS[b.type].storage*b.level,0);
export const unitLevel=(s,id)=>s.research[id]||1;
export function log(s,message){s.log.unshift({time:s.time,message});s.log.length=Math.min(s.log.length,35);}
function credit(s,values){const cap=storageCap(s);for(const k of RESOURCE_KEYS)s.resources[k]=clamp(s.resources[k]+(values[k]||0),0,cap);}
export function affordable(s,cost){return Object.entries(cost).every(([k,v])=>RESOURCE_KEYS.includes(k)&&Number.isFinite(v)&&v>=0&&s.resources[k]>=v);}
function pay(s,cost){for(const[k,v]of Object.entries(cost))s.resources[k]-=v;}
export function buildCost(type,level=1){const spec=BUILDINGS[type],f=level===1?1:Math.pow(1.72,level-1)*.85;return Object.fromEntries(Object.entries(spec.cost).map(([k,v])=>[k,Math.ceil(v*f)]));}
export function duration(type,level=1){return Math.round(BUILDINGS[type].time*(1+(level-1)*1.15));}
export const terrain=W.legacyTerrain;
const groundCache=new WeakMap();
export function groundAt(s,x,y){x=Math.floor(x);y=Math.floor(y);let cache=groundCache.get(s);if(!cache||cache.seed!==s.seed||cache.source!==s.cleared||cache.count!==s.cleared.length){cache={seed:s.seed,source:s.cleared,count:s.cleared.length,cleared:new Set(s.cleared)};groundCache.set(s,cache);}return cache.cleared.has(x+':'+y)?'grass':W.naturalTerrain(s,x,y);}
const workforce=createWorkforce({groundAt,storageCap,log});
const industry=createIndustry({BUILDINGS,storageCap,builders,usedBuilders,log});
