export const searchIsland=expeditions.search,startExpedition=expeditions.start,assignGarrison=expeditions.assign,upgradeColony=expeditions.upgrade,buildSupplyRoute=expeditions.route,sendShipment=expeditions.ship,claimShipments=expeditions.claim,abandonColony=expeditions.abandon,visitColony=expeditions.visit;
