export function startRaid(s){if(s.battle)return false;initGarrison(s);const home=s.buildings.find(b=>b.type==='hq'),dx=s.world?home.x-14:0,dy=s.world?home.y-13:0;const level=hqLevel(s),units=[],types=Object.values(UNITS).filter(u=>!u.archive&&u.hq<=Math.max(1,level)&&!u.heal&&!u.waterborne);for(let i=0;i<3+level;i++){const type=types[Math.floor(rand(i,33,s.seed+Math.floor(s.time))*types.length)].id,u=makeUnit(s,type,1);Object.assign(u,{side:'enemy',x:3+i%3+dx,y:10+Math.floor(i/3)*1.3+dy,damageScale:DIFFICULTIES[s.difficulty].damage*.8,order:{kind:'assault',x:15+dx,y:15+dy}});units.push(u);}s.army.forEach((u,i)=>Object.assign(u,{side:'player',homePosition:s.world?{x:u.x,y:u.y}:null,x:12+i%5*.8+dx,y:20+Math.floor(i/5)*.8+dy,order:{kind:'assault',x:8+dx,y:15+dy},cooldown:0}));s.battle={kind:'raid',name:'Defiende tu base',...(s.world?{world:s.world}:{}),seed:s.seed,elapsed:0,limit:150,buildings:s.buildings.map(b=>({...b,...buildingStats(b.type,b.level),maxHp:buildingStats(b.type,b.level).hp,hp:b.hp,side:'player'})),units:[...s.army,...units],reserve:[],initialBuildings:s.buildings.length,reward:{gold:150+level*50},effects:[],serial:0};s.army=[];log(s,GAME.enemy+' ataca tu base.');return true;}
