export function encode(s,now=Date.now()){return JSON.stringify({...s,savedAt:now});}
export function decode(raw,now=Date.now(),offline=true){if(typeof raw!=='string'||raw.length>3000000)throw Error('Archivo de guardado demasiado grande.');const s=JSON.parse(raw);if(!s||s.version!==1||s.game!==GAME.id)throw Error('La copia pertenece a otro juego o a una versión incompatible.');if(!Number.isFinite(s.time)||s.time<0||!Number.isInteger(s.seed)||!Number.isInteger(s.serial)||s.serial<1)throw Error('Reloj o semilla no válidos.');if(!Object.hasOwn(DIFFICULTIES,s.difficulty))throw Error('Dificultad no válida.');for(const k of RESOURCE_KEYS)if(!Number.isFinite(s.resources?.[k])||s.resources[k]<0||s.resources[k]>1e12)throw Error('Inventario no válido.');if(!Array.isArray(s.buildings)||s.buildings.length>1000||!Array.isArray(s.army)||s.army.length>1000||!Array.isArray(s.training)||s.training.length>300)throw Error('Catálogo del guardado no válido.');W.validateWorld(s);const worldLimit=W.mapSize(s);const validId=id=>typeof id==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,70}$/.test(id);const ids=new Set();for(const b of s.buildings){if(!validId(b.id)||!Object.hasOwn(BUILDINGS,b.type)||!Number.isInteger(b.level)||b.level<1||b.level>10||!Number.isInteger(b.x)||!Number.isInteger(b.y)||b.x<0||b.y<0||b.x+BUILDINGS[b.type].size>worldLimit||b.y+BUILDINGS[b.type].size>worldLimit||!Number.isFinite(b.hp)||b.hp<0||!Number.isFinite(b.stored)||b.stored<0||ids.has(b.id))throw Error('Edificio no válido.');ids.add(b.id);if(b.productionMode!==undefined&&!['cycles'].includes(b.productionMode))throw Error('Modo de producción no válido.');if(b.production&&(!isFactory(b.type)||![0,1,2,3].includes(b.production.index)||!['working','ready'].includes(b.production.status)||!Number.isFinite(b.production.started)||!Number.isFinite(b.production.ends)||b.production.ends<b.production.started||!Number.isFinite(b.production.amount)||b.production.amount<1||b.production.amount>1000000))throw Error('Ciclo de producción no válido.');if(b.job&&(!['build','upgrade','repair'].includes(b.job.kind)||!Number.isFinite(b.job.ends)||!Number.isFinite(b.job.started)||b.job.ends<b.job.started))throw Error('Obra no válida.');}if(s.buildings.filter(b=>b.type==='hq').length!==1)throw Error('Falta el edificio principal.');for(const u of s.army)if(!validId(u.id)||!Object.hasOwn(UNITS,u.type)||!Number.isFinite(u.hp)||u.hp<=0||!Number.isFinite(u.maxHp)||u.maxHp<=0||!Number.isInteger(u.level)||u.level<1||u.level>5)throw Error('Ejército no válido.');for(const t of s.training)if(!validId(t.id)||!Object.hasOwn(UNITS,t.type)||!Number.isFinite(t.ends)||!Number.isFinite(t.started)||!Number.isInteger(t.level)||t.level<1||t.level>5||!ids.has(t.building))throw Error('Cola de entrenamiento no válida.');if(!s.stats||!Array.isArray(s.claimed)||!Array.isArray(s.cleared)||s.cleared.length>worldLimit*worldLimit||!Array.isArray(s.log)||!s.research||!s.completed||!s.settings)throw Error('Copia incompleta.');for(const[k,v]of Object.entries(s.research))if(!Object.hasOwn(UNITS,k)||!Number.isInteger(v)||v<1||v>5)throw Error('Investigación no válida.');if(!s.alliances||typeof s.alliances!=='object')throw Error('Diplomacia no válida.');for(const[id,p]of Object.entries(s.alliances))if(!ALLIES.some(a=>a.id===id)||!Number.isInteger(p.reputation)||p.reputation<0||p.reputation>1000000||!Number.isFinite(p.next))throw Error('Pacto no válido.');if(s.study&&(!Object.hasOwn(UNITS,s.study.type)||!Number.isFinite(s.study.ends)||!Number.isInteger(s.study.level)||s.study.level<2||s.study.level>5))throw Error('Investigación pendiente no válida.');if(s.battle){W.validateWorld(s.battle);if(!['attack','raid','mission','expedition','colony','colony-defense'].includes(s.battle.kind)||!Array.isArray(s.battle.units)||!Array.isArray(s.battle.buildings)||!Array.isArray(s.battle.reserve)||s.battle.units.length>1000||!Number.isFinite(s.battle.elapsed))throw Error('Batalla no válida.');for(const u of[...s.battle.units,...s.battle.reserve])if(!Object.hasOwn(UNITS,u.type)||!Number.isFinite(u.hp)||!Number.isFinite(u.maxHp)||!Number.isInteger(u.level)||!Number.isFinite(u.x??0)||!Number.isFinite(u.y??0))throw Error('Combatiente no válido.');for(const b of s.battle.buildings)if(!Object.hasOwn(BUILDINGS,b.type)||!Number.isFinite(b.hp)||!Number.isFinite(b.x)||!Number.isFinite(b.y))throw Error('Base rival no válida.');}
 if(s.campaign){const c=s.campaign;if(c.version!==1||!c.stars||!c.weekly||!Array.isArray(c.blueprints)||c.blueprints.length>411||c.blueprints.some(t=>!Object.hasOwn(BUILDINGS,t))||!Array.isArray(c.rewards)||c.rewards.length>10000||c.rewards.some(v=>typeof v!=='string'||v.length>60))throw Error('Campaña no válida.');for(const[id,stars]of Object.entries(c.stars))if(!MISSIONS.some(m=>m.id===id)||!Number.isInteger(stars)||stars<1||stars>3)throw Error('Rango de misión no válido.');}
 if(s.events){const e=s.events;if(e.version!==1||!Number.isFinite(e.next)||!Number.isInteger(e.index)||e.index<0||!e.pending||!e.buffs||!Array.isArray(e.history)||e.history.length>30)throw Error('Eventos no válidos.');for(const k of RESOURCE_KEYS)if(!Number.isFinite(e.pending[k])||e.pending[k]<0||e.pending[k]>1e9)throw Error('Recompensa de evento no válida.');if(e.active&&(!Number.isFinite(e.active.started)||!Number.isFinite(e.active.ends)||e.active.ends<e.active.started||!['convoy','refugees','engineers','recon','signal','cache','hospital','solar'].includes(e.active.id)))throw Error('Evento activo no válido.');}
 if(s.battle?.kind==='mission'){const b=s.battle,m=b.mission;if(!m||!MISSIONS.some(v=>v.id===m.id)||![1,2,3].includes(m.rank)||!Array.isArray(m.captured)||!Array.isArray(m.rescued)||m.captured.length>2000||m.rescued.length>2000||!Array.isArray(b.scenery)||b.scenery.length>2000||!Array.isArray(b.deployment?.land)||!Array.isArray(b.deployment?.water)||b.deployment.land.length>150||b.deployment.water.length>60)throw Error('Operación no válida.');for(const p of [...b.deployment.land,...b.deployment.water])if(!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.y<0||p.x>100||p.y>100)throw Error('Despliegue no válido.');if(!b.fog||!Array.isArray(b.fog.explored)||!Array.isArray(b.fog.visible)||b.fog.explored.length>400||b.fog.visible.length>400||[...b.fog.explored,...b.fog.visible].some(v=>!Number.isInteger(v)||v<0||v>399))throw Error('Niebla no válida.');for(const v of b.scenery)if(!Object.hasOwn(BUILDINGS,v.type)||!Number.isFinite(v.x)||!Number.isFinite(v.y))throw Error('Objeto de escenario no válido.');}
 validateFrontier(s);if(!Number.isFinite(s.xp)||s.xp<0)throw Error('Experiencia no válida.');workforce.validate(s);
 if(offline){const elapsed=clamp((now-(s.savedAt||now))/1000,0,8*3600);if(elapsed>5){events.offline(s,elapsed);expeditions.offline(s,elapsed);tickEconomy(s,elapsed,false);s.nextRaid=Math.max(s.nextRaid,s.time+90);log(s,'Se completaron '+Math.floor(elapsed/60)+' minutos de producción y trabajos durante tu ausencia.');}}s.savedAt=now;return s;
}
